import{_ as l,a0 as t,w as d,s as o,ao as c,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"使用位字段和掩碼寫一個國際象棋遊戲 | LCTT x X-CMD","titleTemplate":false,"description":"使用位字段和掩碼寫一個國際象棋遊戲 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用位字段和掩碼寫一個國際象棋遊戲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用位字段和掩碼寫一個國際象棋遊戲 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20210823 Write a chess game using bit-fields and masks","title":"使用位字段和掩碼寫一個國際象棋遊戲","tag":"202208","desc":""},"relativePath":"202208/20210823 Write a chess game using bit-fields and masks.md","filePath":"[post].md"}'),r={name:"202208/20210823 Write a chess game using bit-fields and masks.md"};function h(g,s,k,b,u,f){const n=t("Link");return d(),o("div",null,[s[15]||(s[15]=c(`<h1 id="使用位字段和掩碼寫一個國際象棋遊戲" tabindex="-1">使用位字段和掩碼寫一個國際象棋遊戲 <a class="header-anchor" href="#使用位字段和掩碼寫一個國際象棋遊戲" aria-label="Permalink to “使用位字段和掩碼寫一個國際象棋遊戲”">​</a></h1><blockquote><p>使用位字段和掩碼是不用數據結構組合數據的常用方法。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202208/10/114605qzfzztj2uupb7zuw.jpg" alt=""></p><p>假設你在用 C 語言寫一個國際象棋遊戲。追蹤棋盤上棋子的一種方法是定義一個結構，該結構定義了棋盤上每個可能的棋子及其顏色，因此每個格子都包含該結構中的一個元素。例如，你可以將結構定義成下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>struct chess_pc {</span></span>
<span class="line"><span>   int piece;</span></span>
<span class="line"><span>   int is_black;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>有了這個數據結構，你的程序就會知道每個格子裏是什麼棋子及棋子的顏色。你可以快速識別出棋子是兵、車、馬、象、後還是王，以及棋子是黑還是白。但是，有一種更直接的方法來跟蹤這些信息，同時只用更少的數據和內存。與為棋盤上的每個方格存儲兩個 <code>int</code> 值的結構不同，我們可以存儲單個 <code>int</code> 值，並使用二進制位字段和掩碼來標識每個方格中的棋子和顏色。</p><h3 id="比特和二進制" tabindex="-1">比特和二進制 <a class="header-anchor" href="#比特和二進制" aria-label="Permalink to “比特和二進制”">​</a></h3><p>當使用位字段表示數據時，我們最好像計算機一樣思考。讓我們從列出可能的棋子開始，併為每個棋子分配一個數字。讓我們進入下一個步驟，用二進制表示這個數字，也就是按照計算機追蹤它的方式。記住，二進制數是由比特組成的，比特要麼是 0，要麼是 1。</p><ul><li><code>00000000:</code> 空（0）</li><li><code>00000001:</code> 兵（1）</li><li><code>00000010:</code> 車（2）</li><li><code>00000011:</code> 馬（3）</li><li><code>00000100:</code> 象（4）</li><li><code>00000101:</code> 後（5）</li><li><code>00000110:</code> 王（6）</li></ul><p>要列出一個棋盤上的所有棋子，我們只需要三個比特從右到左依次代表值 1、2 和 4。例如，數字 6 是二進制的 110。6 的二進制表示中的其他所有位都是 0。</p><p>一個聰明一點的方法：我們可以使用那些額外的總是為零的比特來跟蹤一個棋子是黑還是白。我們可以使用數字 8（二進制 <code>00001000</code>）來表示棋子是否為黑色。如果這一位是 1，則代表該棋子是黑色；如果是 0，則代表該棋子是白色。這被稱為<strong>位字段</strong>，稍後我們可以使用二進制<strong>掩碼</strong>將其取出。</p><h3 id="用位字段存儲數據" tabindex="-1">用位字段存儲數據 <a class="header-anchor" href="#用位字段存儲數據" aria-label="Permalink to “用位字段存儲數據”">​</a></h3><p>要編寫一個使用位字段和掩碼的國際象棋程序，我們可以從以下定義開始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/* 棋子 */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#define EMPTY 0</span><span>   // 空</span></span>
<span class="line"><span>#define PAWN 1</span><span>    // 兵</span></span>
<span class="line"><span>#define ROOK 2</span><span>    // 車</span></span>
<span class="line"><span>#define KNIGHT 3</span><span>  // 馬</span></span>
<span class="line"><span>#define BISHOP 4</span><span>  // 象</span></span>
<span class="line"><span>#define QUEEN 5</span><span>   // 後</span></span>
<span class="line"><span>#define KING 6</span><span>    // 王</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/* 棋色 */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#define BLACK 8</span><span>   // 黑</span></span>
<span class="line"><span>#define WHITE 0</span><span>   // 白</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/* 掩碼 */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#define PIECE 7</span></span></code></pre></div><p>當你為一個棋格賦值時，比如初始化棋盤，你可以賦一個 <code>int</code> 類型的值來跟蹤棋子及其顏色。例如，要在棋盤的 <code>0,0</code> 位置存儲棋子黑車，你可以使用下面的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  int board[8][8];</span></span>
<span class="line"><span>..</span></span>
<span class="line"><span>  board[0][0] = BLACK | ROOK;</span></span></code></pre></div><p><code>|</code> 是二進制“或”（<code>OR</code>）操作符，這意味着計算機將合併兩個數字的比特。對於每個比特的位置，如果<strong>任意一個</strong>數字的比特為 1，該位置比特的結果也是 1。<code>BLACK</code> 的值（8，即二進制下的 <code>00001000</code>）和 <code>ROOK</code> 的值（2，即二進制下的 <code>00000010</code>）的二進制或結果是二進制下的 <code>00001010</code>，即 10：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    00001000 = 8</span></span>
<span class="line"><span> OR 00000010 = 2</span></span>
<span class="line"><span>    ________</span></span>
<span class="line"><span>    00001010 = 10</span></span></code></pre></div><p>類似地，要在棋盤的 <code>6,0</code> 位置存儲一個白色兵，你可以這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  board[6][0] = WHITE | PAWN;</span></span></code></pre></div><p>這樣存儲的值就是 <code>WHITE</code>（0）和 <code>PAWN</code>（1）的二進制或的結果，也即是 1。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    00000000 = 0</span></span>
<span class="line"><span> OR 00000001 = 1</span></span>
<span class="line"><span>    ________</span></span>
<span class="line"><span>    00000001 = 1</span></span></code></pre></div><h3 id="用掩碼獲取數據" tabindex="-1">用掩碼獲取數據 <a class="header-anchor" href="#用掩碼獲取數據" aria-label="Permalink to “用掩碼獲取數據”">​</a></h3><p>在下棋過程中，程序需要知道棋格中的棋子和它的顏色。我們可以使用二進制掩碼來分離這部分。</p><p>舉個例子，程序可能需要知道棋局中棋盤上特定棋格的內容，例如位於 <code>board[5][3]</code> 的數組元素。這個是什麼棋子，是黑的還是白的？為了識別棋子，使用二進制“與”（<code>AND</code>）操作符將元素的值與掩碼 <code>PIECE</code> 結合起來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  int board[8][8];</span></span>
<span class="line"><span>  int piece;</span></span>
<span class="line"><span>..</span></span>
<span class="line"><span>  piece = board[5][3] &amp; PIECE;</span></span></code></pre></div><p>二進制“與”（<code>AND</code>）操作符（<code>&amp;</code>）將兩個二進制值結合，這樣對於任意位，如果兩個數字中的那個位<strong>都是</strong> 1，那麼結果也是 1。例如，如果 <code>board[5][3]</code> 的值是 11（二進制下的 <code>00001011</code>），那麼 11 和 掩碼 <code>PIECE</code>（7，二進制下的 <code>00000111</code>）二進制與的結果為二進制下的 <code>00000011</code>，也即 3。這代表馬，馬的值是 3。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    00001011 = 11</span></span>
<span class="line"><span>AND 00000111 = 7</span></span>
<span class="line"><span>    ________</span></span>
<span class="line"><span>    00000011 = 3</span></span></code></pre></div><p>解析棋子的顏色是一個簡單的事情，只需要將棋子的值與 <code>BLACK</code> 位字段進行二進制與操作。比如，你可以寫一個名為 <code>is_black</code> 的函數來確定棋子是黑還是白：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int</span></span>
<span class="line"><span>is_black(int piece)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  return (piece &amp; BLACK);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>之所以可以這樣，是因為 <code>BLACK</code> 的值為 8（二進制下的 <code>00001000</code>）。在 C 語言中，任何非零值都被視為 <code>True</code>，零總是 <code>False</code>。所以如果 <code>5,3</code> 處的棋子是黑色的，則 <code>is_black(board[5][3])</code> 返回 True 值（8）；如果是白色的，則返回 False 值（0）。</p><h3 id="位字段" tabindex="-1">位字段 <a class="header-anchor" href="#位字段" aria-label="Permalink to “位字段”">​</a></h3><p>使用位字段和掩碼是不使用結構組合數據的常用方法。它們值得被程序員收藏到“工具包”中。雖然數據結構對於需要跟蹤相關數據的有序編程是一種有價值的工具，但是使用單獨的元素來跟蹤單個的開或閉值（例如棋子的顏色）的效率較低。在這些情況下，可以考慮使用位字段和掩碼來更高效地組合數據。</p><hr>`,34)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/8/binary-bit-fields-masks"},{default:i(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/21/8/binary-bit-fields-masks",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[2]||(s[2]=[a("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/FYJNEVERFOLLOWS"},{default:i(()=>[...s[4]||(s[4]=[a("FYJNEVERFOLLOWS",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=l(r,[["render",h]]);export{_ as __pageData,y as default};
